ALTER TABLE metering.usage_monthly MODIFY COLUMN http_error_request_count COMMENT '同维度已确认日统计的月合计：该分组中网关可见 HTTP 状态大于等于 400 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN terminal_missing_request_count COMMENT '同维度已确认日统计的月合计：该分组中 terminal_observed 为 0 或 NULL 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN input_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输入 token 总量之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN output_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输出 token 总量之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN total_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输入加输出 token 总量之和；全部未知保持 NULL，不包含子项重复相加';
ALTER TABLE metering.usage_monthly MODIFY COLUMN cached_read_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输入中的缓存读取 token 子项之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN cached_write_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输入中的缓存写入 token 子项之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN reasoning_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的输出中的推理 token 子项之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN reported_total_tokens COMMENT '同维度已确认日统计的月合计；有效统计候选的服务单独上报的总 token 数之和；无已知贡献保持 NULL，已知零保持 0';
ALTER TABLE metering.usage_monthly MODIFY COLUMN cached_read_known_requests COMMENT '同维度已确认日统计的月合计：该分组有效统计候选中 输入中的缓存读取 token 子项非 NULL 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN cached_write_known_requests COMMENT '同维度已确认日统计的月合计：该分组有效统计候选中 输入中的缓存写入 token 子项非 NULL 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN reasoning_known_requests COMMENT '同维度已确认日统计的月合计：该分组有效统计候选中 输出中的推理 token 子项非 NULL 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN reported_total_known_requests COMMENT '同维度已确认日统计的月合计：该分组有效统计候选中 服务单独上报的总 token 数非 NULL 的请求数';
ALTER TABLE metering.usage_monthly MODIFY COLUMN refresh_id COMMENT '生成本次汇总结果或执行记录的刷新 UUID；Worker 发布版本关联标识';
ALTER TABLE metering.usage_monthly MODIFY COLUMN source_watermark COMMENT '本次汇总输入及连续分区水位向量的规范 SHA-256，不是全局 Kafka 截止 offset';
ALTER TABLE metering.usage_monthly MODIFY COLUMN refreshed_at COMMENT '本次汇总刷新或成功发布的 UTC 时间；尚未成功发布时状态表可为 NULL';

ALTER TABLE metering.summary_dirty_notifications MODIFY COMMENT '日期重算通知表；持久记录新增事件、冲突或修复影响的日期';
