ALTER TABLE metering.summary_dirty_notifications MODIFY COLUMN source_id COMMENT '通知来源标识；INGEST 为冻结批次 batch_id，其他原因按各自稳定来源定义';
ALTER TABLE metering.summary_dirty_notifications MODIFY COLUMN evidence_hash COMMENT '触发本日期通知的事件或冲突证据集合的规范 SHA-256';
ALTER TABLE metering.summary_dirty_notifications MODIFY COLUMN kafka_topic COMMENT '事件或处理证据所属的 Kafka topic 名称';
