ALTER TABLE metering.consumer_batch_receipts MODIFY COMMENT '消费批次处理凭据表；证明入库、冲突维护和通知登记已确认可见';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN kafka_topic COMMENT '事件或处理证据所属的 Kafka topic 名称';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN kafka_partition COMMENT 'Kafka 分区编号，offset 只在同一 topic 和分区内比较';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN first_offset COMMENT '所记录 Kafka 分区区间的起始 offset，包含该位置';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN last_offset COMMENT '所记录 Kafka 分区批次的最后 offset，包含该位置';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN batch_id COMMENT '冻结 Kafka 坐标范围及按 offset 排序的消息摘要和校验分类元组的规范 SHA-256';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN next_offset COMMENT '本批最后 offset 加 1；凭据确认可领先于 Kafka 提交，不能直接当连续已提交水位';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN notification_count COMMENT '该批次实际登记并确认可见的日期通知集合大小，可以为 0';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN notification_digest COMMENT '该批次已确认通知集合按日期和通知 ID 排序后的规范 SHA-256';
ALTER TABLE metering.consumer_batch_receipts MODIFY COLUMN confirmed_at COMMENT '批次冻结时记录的 UTC 审计时间，重试沿用；不代表写入确认完成或 Kafka offset 提交的时间';

ALTER TABLE metering.summary_refresh_inputs MODIFY COMMENT '汇总任务输入集合表；保存日任务捕获的精确通知，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_inputs MODIFY COLUMN period_type COMMENT '统计期类型，设计预留 DAY 或 MONTH，结构由未来 Worker 校验';
ALTER TABLE metering.summary_refresh_inputs MODIFY COLUMN period_start COMMENT '统计期 UTC 起始日期；DAY 为当天，MONTH 为自然月首，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_inputs MODIFY COLUMN refresh_id COMMENT '生成本次汇总结果或执行记录的刷新 UUID；Worker 发布版本关联标识';
ALTER TABLE metering.summary_refresh_inputs MODIFY COLUMN notification_id COMMENT '版本化日期、原因、来源及证据元组的规范 SHA-256，实现重算通知幂等';
ALTER TABLE metering.summary_refresh_inputs MODIFY COLUMN captured_at COMMENT '日任务捕获本条通知作为固定输入的 UTC 时间，等待 Worker 实现';

ALTER TABLE metering.summary_refresh_runs MODIFY COMMENT '汇总任务执行审计表；保存阶段、输入与分区校验证据，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN period_type COMMENT '统计期类型，设计预留 DAY 或 MONTH，结构由未来 Worker 校验';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN period_start COMMENT '统计期 UTC 起始日期；DAY 为当天，MONTH 为自然月首，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN refresh_id COMMENT '生成本次汇总结果或执行记录的刷新 UUID；Worker 发布版本关联标识';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN status COMMENT '设计预留执行阶段：RUNNING、PREPARED、PUBLISHING、PUBLISHED 或 FAILED；Worker 尚未实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN publisher_token COMMENT '受保护单个发布者的身份令牌，等待 Worker 实现；不是 Doris 强制 fencing';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN input_count COMMENT '本次捕获的输入项数；日任务为通知数，月任务为日版本项数，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN input_digest COMMENT '本次排序后固定输入集合的规范 SHA-256，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN source_watermark COMMENT '本次汇总输入及连续分区水位向量的规范 SHA-256，不是全局 Kafka 截止 offset';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN source_watermarks_json COMMENT '本次完整连续分区水位向量 JSON，供来源核验与恢复，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN daily_versions_json COMMENT '月任务依赖的日发布版本和覆盖向量 JSON；非月任务可为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN old_partition_id COMMENT '刷新前正式分区的 Doris PartitionId，首次发布可为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN temp_partition_id COMMENT '准备完成的临时分区 Doris PartitionId，用于核验替换结果，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN formal_partition_id COMMENT '当前或发布后正式分区的 Doris PartitionId，尚未确定时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN temp_partition_name COMMENT '本次任务独有的临时分区名称，不接受客户输入，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN expected_row_count COMMENT '准备完成时核验的预期结果行数，0 是有效空分区，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN validation_digest COMMENT '准备或发布结果的校验摘要，待验证时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN error_code COMMENT '固定刷新或发布错误码，无错误时为 NULL，不保存任意异常文本，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN started_at COMMENT '本次刷新任务开始的 UTC 时间，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN updated_at COMMENT '本条任务或统计期状态最近变更的 UTC 时间，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_runs MODIFY COLUMN finished_at COMMENT '本次刷新任务结束的 UTC 时间，尚未结束为 NULL，等待 Worker 实现';

ALTER TABLE metering.summary_refresh_state MODIFY COMMENT '统计期发布状态表；保存版本、覆盖及发布不确定状态，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN period_type COMMENT '统计期类型，设计预留 DAY 或 MONTH，结构由未来 Worker 校验';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN period_start COMMENT '统计期 UTC 起始日期；DAY 为当天，MONTH 为自然月首，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN state_version COMMENT '统计期状态单调递增版本，每次状态转换递增，不使用墙上时钟，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN status COMMENT '设计预留统计期发布状态，EXPIRED 表示覆盖已过期；Worker 与查询 API 尚未实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN active_refresh_id COMMENT '当前活动刷新任务 UUID，无活动任务时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN publication_uncertain COMMENT '正式分区替换结果是否尚未核验；为真时暂停该期成功查询，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN published_refresh_id COMMENT '最近已确认成功发布的刷新 UUID，未发布时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN published_version COMMENT '最近成功发布对应的 state_version，未发布时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN source_watermark COMMENT '本次汇总输入及连续分区水位向量的规范 SHA-256，不是全局 Kafka 截止 offset';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN source_watermarks_json COMMENT '本次完整连续分区水位向量 JSON，供来源核验与恢复，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN daily_versions_json COMMENT '月任务依赖的日发布版本和覆盖向量 JSON；非月任务可为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN formal_partition_id COMMENT '当前或发布后正式分区的 Doris PartitionId，尚未确定时为 NULL，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN coverage_start COMMENT '已确认覆盖日期区间的 UTC 起点，包含该日期，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN coverage_end COMMENT '已确认覆盖日期区间的 UTC 终点，不包含该日期且不包含未来日期，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN error_code COMMENT '固定刷新或发布错误码，无错误时为 NULL，不保存任意异常文本，等待 Worker 实现';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN refreshed_at COMMENT '本次汇总刷新或成功发布的 UTC 时间；尚未成功发布时状态表可为 NULL';
ALTER TABLE metering.summary_refresh_state MODIFY COLUMN updated_at COMMENT '本条任务或统计期状态最近变更的 UTC 时间，等待 Worker 实现';

ALTER TABLE metering.consumer_partition_origins MODIFY COMMENT '消费分区可信起点表；作为连续消费水位和恢复核验的基准';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN group_id COMMENT 'Kafka Consumer 消费组标识，用于隔离各组的可信起点及缺口事实';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN kafka_topic COMMENT '事件或处理证据所属的 Kafka topic 名称';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN kafka_partition COMMENT 'Kafka 分区编号，offset 只在同一 topic 和分区内比较';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN origin_id COMMENT '消费组、topic、分区及可信起点等固定事实的规范 SHA-256';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN initial_offset COMMENT '本消费组分区的可信初始 offset，新组取最早可用位置，已有组需显式接管';
ALTER TABLE metering.consumer_partition_origins MODIFY COLUMN created_at COMMENT '本条恢复事实或通知的 UTC 创建审计时间，不参与稳定标识生成';

ALTER TABLE metering.consumer_partition_gaps MODIFY COMMENT '消费分区缺口事实表；持久记录无法证明完整覆盖的 offset 区间';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN group_id COMMENT 'Kafka Consumer 消费组标识，用于隔离各组的可信起点及缺口事实';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN kafka_topic COMMENT '事件或处理证据所属的 Kafka topic 名称';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN kafka_partition COMMENT 'Kafka 分区编号，offset 只在同一 topic 和分区内比较';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN gap_id COMMENT '消费组分区缺口固定事实的规范 SHA-256，实现同一缺口幂等记录';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN first_offset COMMENT '所记录 Kafka 分区区间的起始 offset，包含该位置';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN next_offset COMMENT '缺口区间的下一 offset，不包含该位置；与 first_offset 组成左闭右开区间';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN reason COMMENT '消费缺口固定原因码；恢复新流量不清除此事实或将历史覆盖变为可信';
ALTER TABLE metering.consumer_partition_gaps MODIFY COLUMN detected_at COMMENT 'Consumer 发现冲突或消费缺口的 UTC 时间';

ALTER VIEW metering.event_variants (
    request_date COMMENT 'UTC 请求日期，由 request_started_at_ms 换算，不由事件到达时间或 UUID 推导',
    logical_request_id COMMENT 'Observer 为一次观察生成的规范 UUIDv4；请求级主标识及 Kafka key',
    event_id COMMENT '事件标识，逻辑请求 ID 加 :start 或 :usage；同 ID 不同内容属于冲突',
    payload_hash COMMENT '当前规范事件 JSON 的 SHA-256；与事件 ID 共同保留内容变体并实现幂等',
    schema_version COMMENT '唯一事件契约版本，当前为 1；未知版本由 Consumer 暂停对应分区',
    event_type COMMENT '事件类型：request_started 或 usage_observed；两者合计仍是一次请求',
    x_request_id COMMENT '网关可见的 X-Request-Id，仅辅助关联；可空、可重复，不用于授权或去重',
    observation_id COMMENT '观察标识，当前与 logical_request_id 相同',
    observation_scope COMMENT '观察范围，当前固定 gateway_response，不代表所有隐藏的上游尝试',
    producer_id COMMENT '生成此事件的 Observer 实例标识，部署时使用实际 Pod UID',
    gateway_instance_id COMMENT '观察请求的网关实例标识，新版为命名空间/Pod名称，历史值可能为Pod UID',
    config_version COMMENT '请求开始时冻结的采集配置版本，需在 Observer 和 Consumer 登记',
    adapter_id COMMENT '响应协议适配器，当前为 chat_completions_v1',
    route_name COMMENT '实际 Envoy HTTP 路由名，不可读时为 unknown；仅诊断，不代表 VirtualService 或归属',
    request_host COMMENT '规范入口 DNS 域名；转小写并去端口及末尾根点，非法输入为 NULL',
    cluster_name COMMENT 'Observer 配置固定的集群名称，业务请求不能覆盖',
    deployment_environment COMMENT 'Observer 固定部署环境：prd、stg 或 dev',
    mapping_status COMMENT '服务解析状态：mapped、unknown_host、invalid_host、lookup_not_implemented、lookup_timeout、lookup_unavailable、lookup_invalid_response、lookup_overloaded、lookup_rate_limited；空 URI 为未实现占位，配置 HTTP/HTTPS 可解析',
    mapping_version COMMENT '成功服务解析快照的规范 SHA-256，绑定 Host、集群、环境及服务和供应商；未知为 NULL',
    customer_mapping_status COMMENT '客户解析状态：mapped、unknown_api_key、invalid_api_key、lookup_not_implemented、lookup_timeout、lookup_unavailable、lookup_invalid_response、lookup_overloaded、lookup_rate_limited；空 URI 为未实现占位，配置 HTTP/HTTPS 可解析',
    customer_mapping_version COMMENT '成功客户解析快照的规范 SHA-256，绑定部署上下文、API Key ID 和客户；未知为 NULL',
    service_id COMMENT '服务接口返回的服务 ID；未实现或失败为 NULL，不使用默认服务补值',
    service_name COMMENT '请求发生时的服务名称快照；解析未知时为 NULL，不用最新名称覆盖历史',
    provider_name COMMENT '请求发生时的供应商名称快照；解析未知时为 NULL，不用最新名称覆盖历史',
    customer_name COMMENT '请求发生时的客户名称快照；解析未知时为 NULL，不用最新名称覆盖历史',
    api_key_id COMMENT '客户接口返回的稳定 API Key ID；未知为 NULL，绝不是原始 Bearer token',
    customer_id COMMENT '与 api_key_id 同次成功解析得到的客户 ID；未知为 NULL，不采信客户端自报 ID',
    provider_id COMMENT '服务接口返回的服务所属供应商 ID；未知为 NULL，不代表隐藏的实际执行方',
    identity_status COMMENT '客户归属状态：known 或 invalid；仅完整客户解析成功为 known，不表示鉴权判定',
    identity_hash COMMENT '固定十五项归属与部署快照元组的规范 SHA-256，不含原始密钥或诊断路由',
    request_started_at_ms COMMENT '网关观察到请求头的 Unix 毫秒时间；决定 UTC 统计日期',
